//! Differential harness: our listing against ObjAsm's.
//!
//!     difftest <our-listing> <objasm-listing>
//!
//! Both listings are normalised, which drops the page headers and other page
//! furniture. They are then compared column by column. So the report says
//! *what* differed (the expanded text, the address, or the generated bytes)
//! rather than only that something did.
//!
//! The three columns are counted separately. Text and address could be made
//! to agree first. The byte column was bound to disagree on instructions
//! until the encoder existed.

use std::path::PathBuf;

use rosasm::listing::{normalise, parse_row, Row};

struct Tally {
    rows: usize,
    text_ok: usize,
    addr_ok: usize,
    bytes_ok: usize,
    bytes_ours_absent: usize,
    /// Rows ObjAsm listed that we never produced.
    missing: usize,
    /// Rows we listed that ObjAsm did not.
    extra: usize,
}

fn compare(ours: &[Row], theirs: &[Row], verbose: bool) -> Tally {
    let mut t = Tally {
        rows: 0,
        text_ok: 0,
        addr_ok: 0,
        bytes_ok: 0,
        bytes_ours_absent: 0,
        missing: 0,
        extra: 0,
    };
    // Walk both listings together, with a limited look-ahead. Lining rows up
    // by the line-number column alone fails on macro expansions, whose line
    // numbers run backwards relative to the invocation. Lining them up by
    // position fails as soon as one side lists a row the other does not. So
    // step through both together while the rows match. On a mismatch, look
    // ahead on both sides for the nearest point where they match again, and
    // count the skipped rows against whichever side had them.
    const LOOKAHEAD: usize = 40;
    let key = |r: &Row| {
        (
            r.num,
            r.text.chars().filter(|c| !c.is_whitespace()).collect::<String>(),
        )
    };
    let mut i = 0usize;
    let mut k = 0usize;
    let mut missing: Vec<Row> = Vec::new();
    let mut extra = 0usize;

    while k < theirs.len() {
        let b = &theirs[k];
        if i >= ours.len() {
            missing.push(b.clone());
            k += 1;
            continue;
        }
        if key(&ours[i]) != key(b) {
            // Find the nearest point where the rows match again: the one
            // with the smallest total skip on both sides.
            let mut best: Option<(usize, usize, usize)> = None; // (cost, di, dk)
            for d in 1..=LOOKAHEAD {
                for (di, dk) in [(d, 0usize), (0usize, d)] {
                    let (ai, bk) = (i + di, k + dk);
                    if ai < ours.len() && bk < theirs.len() && key(&ours[ai]) == key(&theirs[bk]) {
                        let cost = di + dk;
                        if best.is_none_or(|(c, _, _)| cost < c) {
                            best = Some((cost, di, dk));
                        }
                    }
                }
                if best.is_some() {
                    break;
                }
            }
            match best {
                Some((_, di, dk)) => {
                    extra += di;
                    for r in &theirs[k..k + dk] {
                        missing.push(r.clone());
                    }
                    i += di;
                    k += dk;
                    continue;
                }
                None => {
                    // No match within range. Compare these two rows as
                    // they are and move on.
                }
            }
        }
        let a = &ours[i];
        i += 1;
        k += 1;
        t.rows += 1;

        // Compare source text with whitespace removed entirely.
        //
        // Removed, not merely collapsed. ObjAsm wraps its listing at column
        // 72 wherever that falls, even on a space, and that space is then
        // missing from the listing. `either express` comes back as
        // `eitherexpress`, and `label DCD x` as `labelDCD x`, so joining the
        // lines again cannot recover it. Column layout cannot be compared
        // either. Substitution is textual, so replacing `$label` with a
        // shorter name shifts every column after it. What the two sides can
        // be expected to share is the sequence of non-blank characters.
        let strip = |s: &str| s.chars().filter(|c| !c.is_whitespace()).collect::<String>();
        let ca = strip(&a.text);
        let cb = strip(&b.text);
        if ca == cb {
            t.text_ok += 1;
        } else if verbose {
            println!("  line {:?}: text\n    ours   {ca}\n    objasm {cb}", b.num);
        }

        if a.addr == b.addr {
            t.addr_ok += 1;
        } else if verbose {
            println!("  line {:?}: addr ours={:?} objasm={:?}", b.num, a.addr, b.addr);
        }

        if a.bytes == b.bytes {
            t.bytes_ok += 1;
        } else if a.bytes.is_empty() && !b.bytes.is_empty() {
            // We listed no bytes where ObjAsm did. This was expected until
            // the encoder existed.
            t.bytes_ours_absent += 1;
        } else if verbose {
            println!(
                "  line {:?}: bytes ours=[{}] objasm=[{}]",
                b.num, a.bytes, b.bytes
            );
        }
    }
    t.missing = missing.len();
    t.extra = extra;
    if verbose && !missing.is_empty() {
        println!("--- rows ObjAsm listed that we did not ---");
        for r in missing.iter().take(20) {
            println!("  {:?} {}", r.num, r.text);
        }
    }
    t
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let verbose = args.iter().any(|a| a == "-v");
    let files: Vec<PathBuf> = args
        .iter()
        .filter(|a| !a.starts_with('-'))
        .map(PathBuf::from)
        .collect();
    if files.len() != 2 {
        eprintln!("usage: difftest [-v] <our-listing> <objasm-listing>");
        std::process::exit(2);
    }

    let read = |p: &PathBuf| -> Vec<Row> {
        let bytes = std::fs::read(p).unwrap_or_else(|e| {
            eprintln!("difftest: {}: {e}", p.display());
            std::process::exit(1);
        });
        // Listings come off RISC OS as Latin-1.
        let text: String = bytes.iter().map(|&b| b as char).collect();
        normalise(&text).iter().map(|l| parse_row(l)).collect()
    };
    let ours = read(&files[0]);
    let theirs = read(&files[1]);

    println!("rows: ours {} / objasm {}", ours.len(), theirs.len());
    if ours.len() != theirs.len() {
        println!("  (line counts differ — comparing the common prefix)");
    }
    if verbose {
        println!("--- differences ---");
    }
    let t = compare(&ours, &theirs, verbose);
    let pct = |x: usize| if t.rows == 0 { 0.0 } else { 100.0 * x as f64 / t.rows as f64 };
    println!();
    println!("compared rows      {:>6}", t.rows);
    println!("  text matches     {:>6}  {:5.1}%", t.text_ok, pct(t.text_ok));
    println!("  addr matches     {:>6}  {:5.1}%", t.addr_ok, pct(t.addr_ok));
    println!("  bytes match      {:>6}  {:5.1}%", t.bytes_ok, pct(t.bytes_ok));
    println!(
        "  bytes not ours   {:>6}  {:5.1}%   (awaiting the encoder)",
        t.bytes_ours_absent,
        pct(t.bytes_ours_absent)
    );
    println!("rows only ObjAsm listed {:>4}", t.missing);
    println!("rows only we listed      {:>4}", t.extra);

    let hard = t.rows - t.text_ok;
    if hard > 0 || t.missing > 0 || t.extra > 0 {
        std::process::exit(1);
    }
}
